263|        throw new Error(`track ${id} startSec must be >= 0`);
264|      }
265|      if (startSec >= durationSec) {
266|        throw new Error(`track ${id} startSec must be below durationSec`);
267|      }
268|      start = startSec;
269|    }
270|    let loops = true;
271|    if (loop !== undefined) {
272|      if (typeof loop !== "boolean") throw new Error(`track ${id} loop must be a boolean`);
273|      loops = loop;
274|    }
275|    let trackSource: TrackSource | undefined;
276|    if (source !== undefined) {
