283|    const pairs = [
284|      ["artist", artist],
285|      ["composer", composer],
286|      ["license", license],
287|      ["attribution", attribution],
288|    ] as const;
289|    for (const [key, value] of pairs) {
290|      if (value === undefined) continue;
291|      if (!isNonEmptyString(value)) throw new Error(`track ${id} ${key} must be a non-empty string`);
292|      credit[key] = value;
293|    }
294|    if (sourceUrl !== undefined && (typeof sourceUrl !== "string" || !sourceUrl.startsWith("https://"))) {
295|      throw new Error(`track ${id} sourceUrl must be an https URL`);
296|    }
297|    return {
298|      id,
299|      src,
300|      title,
301|      emotion,
302|      vector,
303|      intensity,
304|      tempo,
305|      durationSec,
306|      startSec: start,
307|      loop: loops,
308|      ...credit,
309|      ...(trackSource === undefined ? {} : { source: trackSource }),
310|      ...(sourceUrl === undefined ? {} : { sourceUrl }),
311|    };
312|  });
313|  return { version: SUPPORTED_VERSION, tracks };
