1|"use client";
2|
3|import { useEffect, useRef, useState } from "react";
4|import { MUSIC_CONFIG } from "@/core/music";
5|import type { Track } from "@/core/music";
6|
7|// Two audio elements with equal-power crossfades. Volume lives in a
8|// ref, so the slider never re-runs the track effect or touches src.
9|// Nothing plays before the first user press. Reduced motion only
10|// affects visuals; the audio fade always runs its full length.
11|export function Player({
12|  track,
13|  fadeSec,
14|  sceneTitle,
15|  canSkip,
16|  onSkip,
17|  onEnded,
18|}: {
19|  track: Track | null;
20|  fadeSec: number;
21|  sceneTitle: string | null;
22|  canSkip: boolean;
23|  onSkip: () => void;
24|  onEnded: (trackId: string) => void;
25|}) {
26|  const firstRef = useRef<HTMLAudioElement | null>(null);
27|  const secondRef = useRef<HTMLAudioElement | null>(null);
28|  const audibleRef = useRef(0);
29|  const levelRef = useRef<[number, number]>([1, 0]);
30|  const volumeRef = useRef(0.8);
31|  const fadeRef = useRef<number | null>(null);
32|  const loopArmedRef = useRef<string | null>(null);
33|  const trackRef = useRef<Track | null>(track);
34|  trackRef.current = track;
35|  const fadeSecRef = useRef(fadeSec);
36|  fadeSecRef.current = fadeSec;
37|  const onEndedRef = useRef(onEnded);
38|  onEndedRef.current = onEnded;
39|  const playingRef = useRef(false);
40|  const startedRef = useRef(false);
41|  const firstPlayRef = useRef(true);
42|
43|  // Scheduler fade when set, else the config default; never 0 mid session.
44|  function loopFadeSec() {
45|    return fadeSecRef.current > 0 ? fadeSecRef.current : MUSIC_CONFIG.crossfadeSec;
46|  }
47|  const [started, setStarted] = useState(false);
48|  const [playing, setPlaying] = useState(false);
49|  const [volume, setVolume] = useState(0.8);
50|  const requestPlayRef = useRef((_: Track, __: number) => {});
51|
52|  const [reducedMotion, setReducedMotion] = useState(
53|    () =>
54|      typeof window !== "undefined" &&
55|      !!window.matchMedia?.("(prefers-reduced-motion: reduce)").matches,
56|  );
57|
58|  useEffect(() => {
59|    const query = window.matchMedia?.("(prefers-reduced-motion: reduce)");
60|    if (!query) return;
61|    const onChange = (event: MediaQueryListEvent) => setReducedMotion(event.matches);
62|    query.addEventListener("change", onChange);
63|    return () => query.removeEventListener("change", onChange);
64|  }, []);
65|
66|  function applyLevels() {
67|    const els = [firstRef.current, secondRef.current];
68|    els.forEach((el, i) => {
69|      if (el) el.volume = Math.min(1, Math.max(0, (levelRef.current[i] ?? 0) * volumeRef.current));
70|    });
71|  }
72|
73|  function cancelFade() {
74|    if (fadeRef.current !== null) {
75|      cancelAnimationFrame(fadeRef.current);
76|      fadeRef.current = null;
77|    }
78|  }
79|
80|  // Assigned each render so handlers always see fresh refs. Fades from
81|  // the currently louder element to the newest track; a mid-fade request
82|  // cancels the pending fade and starts from current levels.
83|  requestPlayRef.current = (next: Track, durSec: number) => {
84|    const els = [firstRef.current, secondRef.current];
85|    const srcIdx = (levelRef.current[0] ?? 0) >= (levelRef.current[1] ?? 0) ? 0 : 1;
86|    const dstIdx = 1 - srcIdx;
87|    const srcEl = els[srcIdx];
88|    const dst = els[dstIdx];
89|    if (!srcEl || !dst) return;
90|    cancelFade();
91|    if (trackRef.current?.id !== next.id) loopArmedRef.current = null;
92|    trackRef.current = next;
93|    dst.src = next.src;
94|    dst.onloadedmetadata = () => {
95|      if (next.startSec > 0 && Number.isFinite(dst.duration) && next.startSec < dst.duration) {
96|        try {
97|          dst.currentTime = next.startSec;
98|        } catch {
99|          // Past the end; leave playback at zero.
100|        }
101|      }
102|    };
103|    if (!playingRef.current || durSec <= 0) {
104|      levelRef.current = [0, 0];
105|      levelRef.current[dstIdx] = 1;
106|      audibleRef.current = dstIdx;
107|      srcEl.pause();
108|      applyLevels();
109|      if (playingRef.current) void dst.play().catch(() => undefined);
110|      return;
111|    }
112|    if (playingRef.current) void dst.play().catch(() => undefined);
113|    const startSrc = levelRef.current[srcIdx] ?? 0;
114|    const startDst = levelRef.current[dstIdx] ?? 0;
115|    let t0 = performance.now();
116|    let prev = t0;
117|    const tick = (now: number) => {
118|      // Pause freezes the fade; resume continues from the frozen point.
119|      if (!playingRef.current) {
120|        t0 += now - prev;
121|        prev = now;
122|        fadeRef.current = requestAnimationFrame(tick);
123|        return;
124|      }
125|      prev = now;
126|      const t = Math.min(1, (now - t0) / (durSec * 1000));
127|      levelRef.current[srcIdx] = startSrc * Math.cos((t * Math.PI) / 2);
128|      levelRef.current[dstIdx] = startDst + (1 - startDst) * Math.sin((t * Math.PI) / 2);
129|      applyLevels();
130|      if (t < 1) {
131|        fadeRef.current = requestAnimationFrame(tick);
132|        return;
133|      }
134|      fadeRef.current = null;
135|      levelRef.current[srcIdx] = 0;
136|      levelRef.current[dstIdx] = 1;
137|      audibleRef.current = dstIdx;
138|      applyLevels();
139|      srcEl.pause();
140|    };
141|    fadeRef.current = requestAnimationFrame(tick);
142|  };
143|
144|  const trackId = track?.id ?? null;
145|  useEffect(() => {
146|    const next = trackRef.current;
147|    if (!started || !next) {
148|      // Before the first press, swaps only change src.
149|      if (!started && next) {
150|        const el = [firstRef.current, secondRef.current][audibleRef.current];
151|        if (el && !el.src.endsWith(next.src)) el.src = next.src;
152|      }
153|      return;
154|    }
155|    // The single start path: fade 0 on the very first press.
156|    const dur = firstPlayRef.current ? 0 : fadeSecRef.current;
157|    firstPlayRef.current = false;
158|    requestPlayRef.current(next, dur);
159|  }, [started, trackId]);
160|
161|  useEffect(() => cancelFade, []);
162|
163|  function handleTimeUpdate(index: number, el: HTMLAudioElement) {
164|    const next = trackRef.current;
165|    if (!next || !next.loop || index !== audibleRef.current) return;
166|    const fade = loopFadeSec();
167|    const duration = el.duration;
168|    if (!Number.isFinite(duration) || duration <= fade * 2) return;
169|    const remain = duration - el.currentTime;
170|    if (remain <= fade && loopArmedRef.current !== next.id) {
171|      loopArmedRef.current = next.id;
172|      requestPlayRef.current(next, fade);
173|    } else if (remain > fade + 1) {
174|      loopArmedRef.current = null;
175|    }
176|  }
177|
178|  function handleEnded(index: number) {
179|    const els = [firstRef.current, secondRef.current];
180|    // An element that ends while a fade is running is the one fading out.
181|    if (index !== audibleRef.current || fadeRef.current !== null) {
182|      els[index]?.pause();
183|      return;
184|    }
185|    const next = trackRef.current;
186|    if (!next) return;
187|    if (next.loop) {
188|      requestPlayRef.current(next, loopFadeSec());
189|      return;
190|    }
191|    onEndedRef.current(next.id);
192|  }
193|
194|  function toggle() {
195|    const both = [firstRef.current, secondRef.current];
196|    if (!startedRef.current) {
197|      startedRef.current = true;
198|      setStarted(true);
199|      playingRef.current = true;
200|      setPlaying(true);
201|      return;
202|    }
203|    if (playingRef.current) {
204|      for (const el of both) el?.pause();
205|      playingRef.current = false;
206|      setPlaying(false);
207|      return;
208|    }
209|    playingRef.current = true;
210|    setPlaying(true);
211|    let heard = false;
212|    both.forEach((el, i) => {
213|      if (el && (levelRef.current[i] ?? 0) > 0.02) {
214|        heard = true;
215|        void el.play().catch(() => undefined);
216|      }
217|    });
218|    const next = trackRef.current;
219|    if (!heard && next) requestPlayRef.current(next, 0);
220|  }
221|
222|  function changeVolume(value: number) {
223|    setVolume(value);
224|    volumeRef.current = value;
225|    applyLevels();
226|  }
227|
228|  const credit = track ? [track.composer, track.artist].filter(Boolean).join(", ") : "";
229|  const detail = track
230|    ? [track.emotion, credit || null, track.license || null].filter(Boolean).join(" · ")
231|    : null;
232|
233|  return (
234|    <div className="player" role="region" aria-label="Music player" data-reduced-motion={reducedMotion}>
235|      <audio ref={firstRef} preload="auto" onTimeUpdate={(e) => handleTimeUpdate(0, e.currentTarget)} onEnded={() => handleEnded(0)} />
236|      <audio ref={secondRef} preload="auto" onTimeUpdate={(e) => handleTimeUpdate(1, e.currentTarget)} onEnded={() => handleEnded(1)} />
237|      <button type="button" onClick={toggle} aria-label={playing ? "Pause music" : "Play music"}>
238|        {playing ? "Pause" : "Play"}
239|      </button>
240|      <span className="player-track" aria-live="polite">
241|        {track ? track.title : "Music unavailable"}
242|        {detail ? ` · ${detail}` : ""}
243|        {sceneTitle ? ` · ${sceneTitle}` : ""}
244|      </span>
245|      <label className="player-volume">
246|        Volume
247|        <input
248|          type="range"
249|          min={0}
250|          max={1}
251|          step={0.05}
252|          value={volume}
253|          onChange={(e) => changeVolume(Number(e.target.value))}
254|          aria-label="Volume"
255|        />
256|      </label>
257|      <button type="button" onClick={onSkip} disabled={!canSkip} aria-label="Change track">
258|        Change track
259|      </button>
260|      {track?.attribution ? <span className="player-note">{track.attribution}</span> : null}
261|      {track?.sourceUrl ? (
262|        <a className="player-note" href={track.sourceUrl} rel="noopener noreferrer" target="_blank">
263|          Source
264|        </a>
265|      ) : null}
266|    </div>
267|  );
