1|// Track selection and manifest parsing. Pure: no env, no fetch, no audio.
2|import { EMOTIONS } from "./types";
3|import type { EmotionId, Vector8 } from "./types";
4|import { buildFeatures } from "./cluster";
5|
6|// Hand label for the track: the single emotion it was made to carry.
7|export type TrackSource = "generated" | "jamendo" | "recording";
8|
9|export interface Track {
10|  id: string;
11|  src: string;
12|  title: string;
13|  emotion: EmotionId;
14|  vector: Vector8;
15|  intensity: number;
16|  tempo: number;
17|  durationSec: number;
18|  startSec: number;
19|  loop: boolean;
20|  source?: TrackSource;
21|  artist?: string;
22|  composer?: string;
23|  license?: string;
24|  attribution?: string;
25|  sourceUrl?: string;
26|}
27|
28|export interface MusicManifest {
29|  version: number;
30|  tracks: Track[];
31|}
32|
33|export interface SceneSignal {
34|  vector: Vector8;
35|  intensity: number;
36|  tempo: number;
37|}
38|
39|export type Similarity = (scene: SceneSignal, track: Track, weights: MusicWeights) => number;
40|
41|export interface MusicWeights {
42|  emotion: number;
43|  intensity: number;
44|  tempo: number;
45|}
46|
47|export interface MusicConfig {
48|  similarity: Similarity;
49|  weights: MusicWeights;
50|  switchMargin: number;
51|  dwellSec: number;
52|  minTrackSec: number;
53|  hardCutMargin: number;
54|  crossfadeSec: number;
55|  hardCutCrossfadeSec: number;
56|}
57|
58|// Renormalize the 8 entries to sum 1. Extra keys (such as a Jev
59|// "unknown" entry) are ignored. An all-zero vector stays all zero.
60|export function normalize8(vector: Record<string, number>): number[] {
61|  const values = EMOTIONS.map((id: EmotionId) => {
62|    const v = vector[id];
63|    return typeof v === "number" && Number.isFinite(v) ? v : 0;
64|  });
65|  const sum = values.reduce((a, b) => a + b, 0);
66|  if (sum <= 0) return values.map(() => 0);
67|  return values.map((v) => v / sum);
68|}
69|
70|// Bhattacharyya affinity over the renormalized shapes, plus separate
71|// intensity and tempo terms. Fair to blended scenes, unlike cosine.
72|export function bhattacharyyaSimilarity(
73|  scene: SceneSignal,
74|  track: Track,
75|  weights: MusicWeights = MUSIC_CONFIG.weights,
76|): number {
77|  const s = normalize8(scene.vector);
78|  const t = normalize8(track.vector);
79|  let affinity = 0;
80|  for (let i = 0; i < s.length; i++) {
81|    affinity += Math.sqrt((s[i] ?? 0) * (t[i] ?? 0));
82|  }
83|  return (
84|    weights.emotion * affinity +
85|    weights.intensity * (1 - Math.abs(scene.intensity - track.intensity)) +
86|    weights.tempo * (1 - Math.abs(scene.tempo - track.tempo))
87|  );
88|}
89|
90|// Cosine over buildFeatures output (vector plus weighted intensity and
91|// tempo). Kept as an alternative; it favors peaky scenes.
92|export function cosineSimilarity(scene: SceneSignal, track: Track): number {
93|  const a = buildFeatures(scene);
94|  const b = buildFeatures(track);
95|  let dot = 0;
96|  let na = 0;
97|  let nb = 0;
98|  for (let i = 0; i < a.length; i++) {
99|    const x = a[i] ?? 0;
100|    const y = b[i] ?? 0;
101|    dot += x * y;
102|    na += x * x;
103|    nb += y * y;
104|  }
105|  if (na === 0 || nb === 0) return 0;
106|  return dot / (Math.sqrt(na) * Math.sqrt(nb));
107|}
108|
109|export const MUSIC_CONFIG: MusicConfig = {
110|  similarity: bhattacharyyaSimilarity,
111|  weights: { emotion: 0.7, intensity: 0.15, tempo: 0.15 },
112|  switchMargin: 0.07,
113|  dwellSec: 20,
114|  minTrackSec: 45,
115|  hardCutMargin: 0.2,
116|  crossfadeSec: 3,
117|  hardCutCrossfadeSec: 1.5,
118|};
119|
120|export function resolveConfig(override?: Partial<MusicConfig>): MusicConfig {
121|  if (!override) return MUSIC_CONFIG;
122|  return {
123|    ...MUSIC_CONFIG,
124|    ...override,
125|    weights: override.weights ?? MUSIC_CONFIG.weights,
126|  };
127|}
128|
129|export function scoreTrack(
130|  scene: SceneSignal,
131|  track: Track,
132|  override?: Partial<MusicConfig>,
133|): number {
134|  const config = resolveConfig(override);
135|  return config.similarity(scene, track, config.weights);
136|}
137|
138|// Best score first. Ties go to the lower track id, so ranking is stable.
139|export function rankTracks(
140|  scene: SceneSignal,
141|  manifest: MusicManifest,
142|  override?: Partial<MusicConfig>,
143|): Track[] {
144|  const config = resolveConfig(override);
145|  return [...manifest.tracks].sort((a, b) => {
146|    const diff =
147|      config.similarity(scene, b, config.weights) - config.similarity(scene, a, config.weights);
148|    if (diff !== 0) return diff;
149|    return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
150|  });
151|}
152|
153|// Dominant emotion of a scene: argmax of the renormalized vector, with
154|// ties broken by EMOTIONS order.
155|export function dominantEmotion(scene: SceneSignal): EmotionId {
156|  const norm = normalize8(scene.vector);
157|  let best: EmotionId = EMOTIONS[0] as EmotionId;
158|  let bestValue = -Infinity;
159|  EMOTIONS.forEach((id: EmotionId, i: number) => {
160|    const value = norm[i] ?? 0;
161|    if (value > bestValue) {
162|      bestValue = value;
163|      best = id;
164|    }
165|  });
166|  return best;
167|}
168|
169|// Reader skip rule: cycle tracks hand-labeled with the scene's dominant
170|// emotion, in score order, wrapping and skipping the current track. When
171|// the current track has another emotion, start at the top candidate. With
172|// no other same-emotion track, fall back to the best track overall that
173|// is not the current one. A null scene cycles all tracks in id order.
174|// One track or none gives null, and the UI disables the button then.
175|export function nextTrack(
176|  scene: SceneSignal | null,
177|  manifest: MusicManifest,
178|  currentTrackId: string | null,
179|  override?: Partial<MusicConfig>,
180|): Track | null {
181|  const tracks = manifest.tracks;
182|  if (tracks.length <= 1) return null;
183|  const config = resolveConfig(override);
184|  if (scene === null) {
185|    const ids = [...tracks].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
186|    const at = ids.findIndex((t) => t.id === currentTrackId);
187|    return ids[(at + 1) % ids.length] as Track;
188|  }
189|  const ranked = rankTracks(scene, manifest, config);
190|  const same = ranked.filter((t) => t.emotion === dominantEmotion(scene));
191|  const others = same.filter((t) => t.id !== currentTrackId);
192|  if (others.length > 0) {
193|    const at = same.findIndex((t) => t.id === currentTrackId);
194|    if (at >= 0) return same[(at + 1) % same.length] as Track;
195|    return same[0] as Track;
196|  }
197|  return ranked.find((t) => t.id !== currentTrackId) ?? null;
198|}
199|
200|const SUPPORTED_VERSION = 2;
201|const SOURCES = ["generated", "jamendo", "recording"] as const;
202|
203|function isRecord(value: unknown): value is Record<string, unknown> {
204|  return typeof value === "object" && value !== null && !Array.isArray(value);
205|}
206|
207|function isOneOf<T extends string>(value: unknown, allowed: readonly T[]): value is T {
208|  return typeof value === "string" && allowed.some((entry) => entry === value);
209|}
210|
211|function isVector8(value: unknown): value is Vector8 {
212|  if (!isRecord(value)) return false;
213|  return EMOTIONS.every(
214|    (id: EmotionId) =>
215|      typeof value[id] === "number" &&
216|      Number.isFinite(value[id]) &&
217|      (value[id] as number) >= 0 &&
218|      (value[id] as number) <= 1,
219|  );
220|}
221|
222|function isUnit(value: unknown): value is number {
223|  return typeof value === "number" && Number.isFinite(value) && value >= 0 && value <= 1;
224|}
225|
226|function isSrc(value: unknown): value is string {
227|  return (
228|    typeof value === "string" && (value.startsWith("/music/") || value.startsWith("https://"))
229|  );
230|}
231|
232|function isNonEmptyString(value: unknown): value is string {
233|  return typeof value === "string" && value !== "";
234|}
235|
236|// Fail loudly on a bad drop-in manifest so broken files never play quiet.
237|export function parseManifest(json: unknown): MusicManifest {
238|  if (!isRecord(json)) throw new Error("manifest must be an object");
239|  if (json.version !== SUPPORTED_VERSION) {
240|    throw new Error(`unsupported manifest version: ${String(json.version)}`);
241|  }
242|  if (!Array.isArray(json.tracks)) throw new Error("manifest tracks must be an array");
243|  const tracks = json.tracks.map((entry, i) => {
244|    if (!isRecord(entry)) throw new Error(`track ${i} must be an object`);
245|    const { id, src, title, emotion, vector, intensity, tempo } = entry;
246|    const { durationSec, startSec, loop } = entry;
247|    const { source, artist, composer, license, attribution, sourceUrl } = entry;
248|    if (typeof id !== "string" || id === "") throw new Error(`track ${i} needs a string id`);
