99|function stagedPaths() {
100|  const output = execFileSync(
101|    'git',
102|    ['diff', '--cached', '--name-only', '--diff-filter=ACMR', '-z'],
103|    { encoding: 'buffer', stdio: ['ignore', 'pipe', 'ignore'] },
104|  );
105|  const text = output.toString('utf8');
106|  return text.length === 0 ? [] : text.split('\0').filter((entry) => entry !== '');
107|}
108|
109|// Pure and testable: flags from `git diff --numstat -z` output. Each record is
110|// one NUL-terminated "added\tdeleted\tpath" chunk; a rename is a chunk with
111|// an empty path followed by old-name and new-name chunks, keyed on the new.
112|export function parseNumstatZ(text) {
113|  const flags = new Map();
114|  if (text.length === 0) return flags;
115|  const parts = text.split('\0');
116|  for (let i = 0; i < parts.length; i++) {
117|    const chunk = parts[i];
118|    if (chunk === '') continue;
119|    const record = /^(\d+|-)\t(\d+|-)\t([\s\S]*)$/.exec(chunk);
120|    if (!record) continue;
121|    const isBinary = record[1] === '-' && record[2] === '-';
122|    let path = record[3];
123|    if (path === '') {
124|      const renamed = parts[i + 2];
125|      i += 2;
126|      if (renamed === undefined || renamed === '') continue;
127|      path = renamed;
128|    }
129|    flags.set(path, isBinary);
130|  }
131|  return flags;
132|}
