134|// Binary flags from git's own numstat: git prints "-\t-\t" for files whose
135|// first 8000 bytes hold a NUL byte, so this reuses that detection.
136|function stagedBinaryFlags() {
137|  const output = execFileSync(
138|    'git',
139|    ['diff', '--cached', '--numstat', '--diff-filter=ACMR', '-z'],
140|    { encoding: 'buffer', stdio: ['ignore', 'pipe', 'ignore'] },
141|  );
142|  return parseNumstatZ(output.toString('utf8'));
143|}
144|
145|function stagedBlobSize(path) {
146|  const output = execFileSync('git', ['cat-file', '-s', ':' + path], {
147|    encoding: 'utf8',
148|    stdio: ['ignore', 'pipe', 'ignore'],
149|  });
150|  return Number.parseInt(output.trim(), 10);
151|}
152|
153|function main() {
154|  let paths;
155|  let binaryFlags = new Map();
156|  try {
157|    paths = stagedPaths();
158|    binaryFlags = stagedBinaryFlags();
159|  } catch {
160|    console.error('warning: not a git repo, skipping the file-size check');
161|    return 0;
162|  }
163|  const entries = [];
164|  for (const path of paths) {
165|    if (isIgnored(path)) continue;
166|    let bytes;
167|    try {
168|      bytes = stagedBlobSize(path);
169|    } catch {
170|      continue; // Left the index since the diff was read.
171|    }
172|    entries.push({ path, bytes, isBinary: binaryFlags.get(path) === true });
173|  }
174|  const oversized = findOversized(entries);
175|  if (oversized.length === 0) return 0;
176|  console.error(`error: ${oversized.length} staged file(s) over the ${MAX_TOKENS}-token limit (tokens = ceil(bytes/4)):`);
177|  for (const file of oversized) {
178|    console.error(`  ${file.path}: ${file.bytes} bytes, about ${file.tokens} tokens`);
179|  }
180|  console.error('');
181|  console.error(SPLIT_HELP);
182|  return 1;
183|}
184|
185|const invokedAsScript = process.argv[1] === fileURLToPath(import.meta.url);
186|if (invokedAsScript) process.exit(main());

